-- A Link to the Past (SNES): the game's maps. The overworld from VGMaps'
-- Light and Dark World rips, the dungeons from Ian Albert's maps
-- (ian-albert.com, free to use; built from the game's own room data).
-- Hyrule is one map with the Light and Dark World as its two versions, the
-- dungeons one map each with a version per floor, as OoT's are. Replaces the
-- old Portuguese categories, which never had markers. Generated by
-- gen_maps.py. Harmless to run again.

DELETE FROM marker_category WHERE container_id = 3 AND id BETWEEN 300 AND 330 AND parent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM marker WHERE marker_category_id BETWEEN 300 AND 330);
DELETE FROM marker_category WHERE container_id = 3 AND id BETWEEN 300 AND 330 AND NOT EXISTS (SELECT 1 FROM marker WHERE marker_category_id BETWEEN 300 AND 330) AND NOT EXISTS (SELECT 1 FROM (SELECT parent_id FROM marker_category WHERE parent_id BETWEEN 300 AND 330) c);
UPDATE container SET default_zoom = 1, max_zoom = 6, icon = 'A-Link-to-the-Past' WHERE id = 3;
UPDATE map SET name = 'Hyrule', kind = 'world', default_zoom = 1, max_zoom = 4, map_order = 0, map_copyright = 'Map artwork &#169; Nintendo.' WHERE id = 3;
UPDATE submap SET name = 'Light World', tile_url = 'alttp/v1/light-world/', tile_ext = 'webp', tile_version = '5e17982bfad5ddfc', bounds = '[[-256,0],[0,256]]', mapper_id = (SELECT id FROM mapper WHERE name = 'JonLeung' ORDER BY id LIMIT 1), submap_order = 1, is_default = 1 WHERE id = 140;
UPDATE submap SET name = 'Dark World', tile_url = 'alttp/v1/dark-world/', tile_ext = 'webp', tile_version = '011cc1228f7e07d0', bounds = '[[-256,0],[0,256]]', mapper_id = (SELECT id FROM mapper WHERE name = 'Alex Foster' ORDER BY id LIMIT 1), submap_order = 2, is_default = 0 WHERE id = 141;
